class LRUCache:
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if key not in self.cache:
            return None
        # Move to end to mark as most recently used
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            # Pop the first item (least recently used)
            self.cache.popitem(last=False)

    def __len__(self):
        return len(self.cache)

    def keys(self):
        return list(self.cache.keys())

def flatten_dict(d, sep="."):
    """
    Flattens a nested dictionary into a single-level dictionary.
    The key of a nested value is the path of keys joined with `sep`.
    Only dictionaries are descended into.
    """
    result = {}

    def _recurse(current_dict, parent_key=""):
        # If the dictionary is empty, we keep it as is
        if not current_dict:
            result[parent_key] = {}
            return

        for key, value in current_dict.items():
            # Construct the new key path
            new_key = f"{parent_key}{sep}{key}" if parent_key else key

            if isinstance(value, dict) and value:
                # If value is a non-empty dictionary, descend
                _recurse(value, new_key)
            elif isinstance(value, dict) and not value:
                # If value is an empty dictionary, keep it as is
                result[new_key] = {}
            else:
                # If value is not a dictionary (or is a list/other), keep it
                result[new_key] = value

    _recurse(d)
    return result

def median(values):
    if not values:
        raise ValueError("List must not be empty")
    s = sorted(values)
    n = len(s)
    if n % 2 == 1:
        return s[n // 2]
    else:
        return (s[n // 2 - 1] + s[n // 2]) / 2

def chunked(items, size):
