def top_words(text, n):
    counts = {}
    punctuation = '.,;:!?'
    for w in text.split():
        # Strip punctuation from start and end
        clean_w = w.strip(punctuation).lower()
        if clean_w:
            counts[clean_w] = counts.get(clean_w, 0) + 1

    # Sort by count descending, then by word ascending
    # We use -x[1] for count to sort descending, and x[0] for word to sort ascending
    sorted_items = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    return [item[0] for item in sorted_items[:n]]

