class TTLCache:
    def __init__(self, capacity, ttl, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be greater than 0")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        # Stores {key: [value, expiry_time]}
        self.cache = {}
        # Stores keys in order of use (LRU)
        self.order = deque()

    def put(self, key, value):
        now = self.clock()
        expiry = now + self.ttl

        if key in self.cache:
            # Remove from order to move to end (most recent)
            self.order.remove(key)
        else:
            # Before adding, check if we need to evict
            # First, remove expired entries to free up space
            self._evict_expired()

            # If still at capacity, remove LRU
            if len(self.cache) >= self.capacity:
                lru_key = self.order.popleft()
                del self.cache[lru_key]

        self.cache[key] = [value, expiry]
        self.order.append(key)

    def get(self, key):
        if key not in self.cache:
            return None

        value, expiry = self.cache[key]
        if self.clock() >= expiry:
            # Expired
            self.order.remove(key)
            del self.cache[key]
            return None

        # Move to end (most recent)
        self.order.remove(key)
        self.order.append(key)
        return value

    def _evict_expired(self):
        now = self.clock()
        # We must iterate over a copy or list because we delete during iteration
        keys_to_del = []
        for k, (v, expiry) in self.cache.items():
            if now >= expiry:
                keys_to_del.append(k)

        for k in keys_to_del:
            self.order.remove(k)
            del self.cache[k]

    def __len__(self):
        now = self.clock()
        count = 0
        for k, (v, expiry) in self.cache.items():
            if now < expiry:
                count += 1
        return count

    def keys(self):
        now = self.clock()
        valid_keys = []
        for k in self.order:
            if now < self.cache[k][1]:
                valid_keys.append(k)
        return valid_keys

